INSERT INTO `flag_duty_reports` (`id`, `schedule_id`, `content`, `photo_url`, `reported_by`, `created_at`, `academic_year`, `semester`) VALUES
(1, 13, 'กล่าวต้อนรับนักเรียน นักศึกษา ในโอกาสเปิดภาคเรียนที่ 2 ปีการศึกษา 2569', NULL, 408, '2026-10-21 11:22:47', '2569', '2'),
(2, 14, 'การมาเรียนในวิทยาลัย การจัดการเรียนการสอน และห่วงใยเนื่องจากสถานน้ำท่วม', NULL, 408, '2026-10-21 11:23:34', '2569', '2'),
(3, 15, 'แจ้งประชาสัมพันธ์เกี่ยวกับสถานการณ์น้ำท่วม และให้กำลังใจนักเรียน นักศึกษาที่ประสบอุทกภัยในครั้งนี้', NULL, 408, '2026-10-21 11:24:15', '2569', '2'),
(4, 2, 'การยิ้มไหว้ทักทาย\r\nการขับขี่รถด้วยความปลอดภัย\r\nการดูแลสุขภาพตนเองหลั่งน้ำท่วม', '/uploads/flag-duty/1792975996782-270535341.jpg', 415, '2026-10-26 07:53:16', '2569', '2'),
(5, 1, '1 การเฝ้าระวังสัตว์มีพิษหลังน้ำท่วม\r\n2 การใช้รถใช้ถนน', NULL, 413, '2026-10-26 08:03:56', '2569', '2'),
(6, 3, 'การเข้าตรวจสอบผลการเรียนและการโหลดใบลงทะเบียนเรียนในภาคเรียนที่2/2569 ใน2ช่องทาง 1.ระบบศธ.02ออนไลน์ 2.เว็บไซต์ของวิทยาลัย', '/uploads/flag-duty/1793063735646-236668699.jpg', 411, '2026-10-27 08:15:35', '2569', '2'),
(7, 4, 'การประชาสัมพันธ์รับสมัครเรียนประจำปีการศึกษา 2570\r\nการลงทะเบียนเรียน', '/uploads/flag-duty/1793149906182-608577645.jpg', 412, '2026-10-28 08:11:46', '2569', '2'),
(8, 5, 'การส่งเอกสารเงินเรียนฟรี\r\nการช่วยกันประหยัดไฟฟ้า', NULL, 419, '2026-10-30 07:48:31', '2569', '2'),
(9, 6, 'พูดเรื่องการลงทะเบียนเรียนซ่อมรายวิชา ในภาคเรียน S ซัมเมอร์ปีการศึกษา 2569', NULL, 422, '2026-10-30 08:00:46', '2569', '2'),
(10, 7, 'ประชาสัมพันธ์ การหารายได้ part time ณ บ. Pizza company ปั้ม ptt องครักษ์', '/uploads/flag-duty/1793589326568-840298013.jpeg', 423, '2026-11-02 10:15:26', '2569', '2'),
(11, 8, 'ประชาสัมพันธ์วันแข่งทักษะพื้นฐาน ทักษะวิชาวิชาชีพ ในวันที่5-6 พย.69 ที่วิทยาลัยที่เทคนครนายก วิทยาลัยการอาชีพนครนายก วิทยาลัยการอาชีพองครักษ์  และสิ่งประดิษฐ์ระดับชาติ ในวันที่9พ.ย. 69 ที่วิทยาลัยเทคนิคปทุมธานี', NULL, 425, '2026-11-03 07:56:39', '2569', '2'),
(12, 10, 'ให้กำลังใจนักเรียน นักศึกษา ที่เข้าร่วมการแข่งขันทักษะวิชาชีพ และทักษะพื้นฐาน ประจำปีการศึกษา 2569 ระดับอาชีวศึกษาจังหวัดนครนายก', NULL, 408, '2026-11-05 15:03:35', '2569', '2'),
(13, 11, 'การรับสมัครเรียนปีการศึกษา 2570 การรับสมัครทุนการศึกษาทุน ยุวพัฒน์ ', '/uploads/flag-duty/1793954565163-487990297.jpg', 409, '2026-11-06 15:42:45', '2569', '2');

