--
-- Table structure for table `homeroom_reports`
--

CREATE TABLE `homeroom_reports` (
  `id` int(11) NOT NULL,
  `week_id` int(11) NOT NULL,
  `level_id` int(11) NOT NULL,
  `major_id` int(11) NOT NULL,
  `academic_year` varchar(16) NOT NULL,
  `semester` varchar(4) NOT NULL CHECK (`semester` in ('1','2')),
  `announce_text` text NOT NULL,
  `problem_text` text DEFAULT NULL,
  `solution_text` text DEFAULT NULL,
  `reported_by` int(11) NOT NULL,
  `created_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `homeroom_reports`
--

INSERT INTO `homeroom_reports` (`id`, `week_id`, `level_id`, `major_id`, `academic_year`, `semester`, `announce_text`, `problem_text`, `solution_text`, `reported_by`, `created_at`) VALUES
(1, 1, 5, 5, '2569', '2', 'สอบถามปัญหาการมาเรียน เนื่องจากสถานการณ์น้ำท่วม', 'มีนักศึกษามาเรียนไม่ได้ 2 คน', 'ติดตามเยี่ยมบ้าน และให้แนวทางในการปฏิบัติตนเรียบร้อยแล้ว', 408, '2026-10-21 11:20:30'),
(2, 1, 3, 2, '2569', '2', 'ปรึกษาผลกระทบน้ำท่วม', 'นักเรียนติดน้ำท่วมยังไม่สามารถมาได้ครบ', 'แจ้งให้นักเรียนรักษาสุขภาพสำหรับบ้านที่ยังน้ำท่วมอยู่ สำหรับคนที่มาได้ก็ให้เดินทางมาเรียน', 430, '2026-10-21 13:11:43'),
(3, 1, 2, 1, '2569', '2', 'การลงทะเบียนเรียน\r\nการมาเรียน\r\n', '-', '-', 419, '2026-10-21 13:22:40'),
(4, 1, 4, 4, '2569', '2', 'กำหนดการมาเรียน การลงทะเบียนเรียนในภาคเรียนที่ 2/2569', '-', '-', 416, '2026-10-21 13:22:49'),
(5, 1, 5, 2, '2569', '2', 'ความระมัดระวังในการเดินทางมาเรียน เนื่องจากบ้านนักศึกษายังมีน้ำท่วมขัง ', 'ปัญหาน้ำท่วมขัง ', 'นักศึกษานั่งเรือออกมาขึ้นรถหน้าถนน ', 433, '2026-10-21 13:22:57'),
(6, 1, 5, 3, '2569', '2', '-', 'สอบถามเรื่องน้ำท่วม', 'แก้ไขและห่วงใยออกเยี่ยมบ้าน', 434, '2026-10-21 13:24:35'),
(7, 1, 1, 5, '2569', '2', 'การมาเรียนในสถานการณ์น้ำท่วม  การปรับตัวในการมาเรียน', 'มาสายบ้างเป็นบางวัน', 'พูดคุย สอบถามปัญหาร่วมหาแนวทางแก้ไข', 409, '2026-10-21 13:31:13'),
(8, 1, 4, 5, '2569', '2', 'การเปิดภาคเรียนที่2ปี2569  การช่วยเหลือซึ่งกันและกัน การมีมนุษย์สัมพันธ์ที่ดี', 'นักศึกษาหลายคนยังประสบปัยหาน้ำยังท่วมขังอยู่ จึงมาเรียนไม่ได้ในสปดาห์นี้', 'เตรียมออกเยียมบ้าน', 411, '2026-10-21 13:35:28'),
(9, 1, 1, 3, '2569', '2', 'การลงทะเบียนเรียนภาคเรียนที่2/2569', NULL, NULL, 415, '2026-10-21 13:36:04'),
(10, 1, 5, 4, '2569', '2', 'แจ้งกำหนดการแข่งขันทักษะวิชาชีพ 2569', 'นักศึกษาประสบอุทกภัย ยังไม่สามารถเดินทางมาวิทยาลัยฯ ได้', 'ออกเยี่ยมบ้านนักศึกษาร่วมกับผู้บริหาร คณะรรูประจำแผนกวิชาการจัดการ และ นักเรียน เพื่อส่งต่อความห่วงใย และให้ความช่วยเหลือ', 423, '2026-10-21 14:00:04'),
(11, 1, 1, 1, '2569', '2', 'สอบถามสภาพปัญหาการเดินทางมาวิทยาลัยของนักเรียน', NULL, NULL, 424, '2026-10-21 14:25:51'),
(12, 1, 3, 5, '2569', '2', 'สอบถามความเป็นอยุ่หลังจากเกิด น้ำท่วม', 'ไม่มีเสื้อผ้าใส่ มาเรียน', 'รอน้ำลด 3-4 วันจะรีบเตรียมออกไปหาซื้อ อุปกรณ์', 428, '2026-10-21 14:43:53'),
(13, 1, 2, 5, '2569', '2', 'การทำเล่มโครงการ อวท.', '-', '-', 431, '2026-10-21 15:31:03'),
(14, 1, 1, 4, '2569', '2', 'บ้านนักเรียน เกิด อุทกภัย ', 'ไม่มี', 'ออกเยี่ยมบ้าน บ้านเกิด น้ำท่วม', 429, '2026-10-21 15:34:19'),
(15, 1, 3, 4, '2569', '2', ' สอบถามเรื่องสภาพน้ำท่วมในปัจจุบัน         การเตรียมความพร้อมในการมาเรียน', 'ยังไม่พร้อมมาเรียนเนื่องจากรถรับส่งยังไม่วิ่ง และน้ำยังท่วมขัง', 'ครูเดินทางไปมอบถุงยังชีพและเยี่ยมบ้าน', 412, '2026-10-21 17:33:14'),
(16, 1, 2, 3, '2569', '2', 'พูดคุยเรื่องการเรียนในวันเปิดเทอม2/69', 'นักเรียนที่ลาเนื่องจากน้ำท่วม', '-', 418, '2026-10-22 07:47:05'),
(17, 1, 3, 3, '2569', '2', 'พูดคุยเรื่องการเรียนในวันเปิดเทอม2/69', '-', '-', 418, '2026-10-22 07:47:42'),
(18, 1, 2, 4, '2569', '2', 'ได้ติดตามสอบถามความเป็นอยู่ของนักเรียนและครอบครัวที่ได้รับผลกระทบจากสถานการณ์น้ำท่วม โดยสอบถามสภาพบ้านเรือน ความปลอดภัยในการเดินทาง และผลกระทบต่อการดำรงชีวิตและการมาเรียน พร้อมทั้งให้คำแนะนำในการดูแลสุขภาพและความปลอดภัยในช่วงน้ำท่วม รวมถึงแจ้งให้นักเรียนติดต่อครูที่ปรึกษาหากประสบปัญหาหรือมีความจำเป็นต้องได้รับความช่วยเหลือ', '-', '-', 432, '2026-10-22 07:50:52'),
(19, 1, 2, 2, '2569', '2', '1. แจ้งนักเรียนเรื่องการมาเรียนในช่วงน้ำยังท่วมในบางพื้นที่\r\n2. แจ้งเรื่องการลงทะเบียนเรียน ในภาคเรียนที่ 2/2569\r\n3. สอบถามสถานการณ์น้ำท่วมบ้านพักของนักเรียน', '-', '-', 410, '2026-10-27 13:26:32'),
(20, 1, 4, 2, '2569', '2', '1. แจ้งเรื่องการมาเรียนในช่วงสัปดาห์ที่ 1-3 เนื่องจากบางพื้นที่ยังมีสถานการณ์น้ำท่วม\r\n2. แจ้งเรื่องการลงทะเบียนเรียน ประจำภาคเรียนที่ 2/2569\r\n3. สอบถามสถานการณ์น้ำท่วมบ้านของนักศึกษา', '-', '-', 410, '2026-10-27 13:55:49'),
(21, 1, 5, 1, '2569', '2', 'สอบถามเรื่องระดับน้ำคนที่ประสบภัย', NULL, 'โทรศัพท์สอบถามความเป็นอยู่นักเรียนกับผู้ปกครอง', 421, '2026-10-28 11:00:47'),
(22, 2, 5, 5, '2569', '2', 'การชำระค่าลงทะเบียนเรียน ขยายเวลาถึง 13 พ.ย. 69 และเรื่องการแต่งกายในแต่ละวัน', 'นักศึกษาแต่งกายไม่ถูกระเบียบ 1 คน', 'ได้แจ้งให้แก้ไขเรียบร้อยแล้ว', 408, '2026-10-28 12:21:15'),
(23, 2, 3, 2, '2569', '2', 'แจ้งให้นักเรียนเรื่องการลงทะเบียนเรียน', NULL, NULL, 430, '2026-10-28 13:00:34'),
(24, 2, 4, 4, '2569', '2', 'การมาเรียน  การลงทะเบียนเรียนในภาคเรียนที่ 2/2569', '-', '-', 416, '2026-10-28 13:05:14'),
(25, 2, 1, 3, '2569', '2', 'การลงทะเบียนเรียนภาคเรียนที่ 2 ปีการศึกษา 2569\r\nการรักษาความสะอาดห้องเรียนและบริเวณโรงเรียน', NULL, NULL, 415, '2026-10-28 13:18:16'),
(26, 2, 5, 2, '2569', '2', 'การวางแผนการจัดทำโปรเจ็คจบ การเข้าร่วมกิจกรรมหน้าเสาธง ', '-', '-', 433, '2026-10-28 13:18:48'),
(27, 2, 2, 3, '2569', '2', 'การเข้าแถวเคารพธงชาติ ช่วงนี้เด็กเริ่มทยอยมารร.หลังจากน้ำท่วมบ้าน', '-', '-', 418, '2026-10-28 13:19:39'),
(28, 2, 2, 1, '2569', '2', '-การเตรียมตัวหาที่ฝึกงาน\r\n-ค่าลงทะเบียนเรียน\r\n-การเข้าร่วมกิจกรรม', '-', '-', 419, '2026-10-28 13:19:39'),
(29, 2, 3, 3, '2569', '2', 'การเข้าแถวเคารพธงชาติ ช่วงนี้เด็กเริ่มทยอยมารร.หลังจากน้ำท่วมบ้าน', '-', '-', 418, '2026-10-28 13:20:38'),
(30, 2, 4, 5, '2569', '2', '-การลงทะเบียนเรียนสำหรับคนที่ยังไม่ชำระค่าเทอมให้รีบดำเนินการหมดเขตวันที่13 พฤศจิกายน 2569\r\n-การเข้าร่วมกิจกรรมต่างๆของวิทยาลัย\r\n', NULL, NULL, 411, '2026-10-28 13:26:07'),
(31, 2, 5, 4, '2569', '2', '1. แจ้งกำหนดการลงทะเบียนและเงื่ิอนไขในการขอผ่อนผันการลงทะเบียนเรียนประจำภาคเรียนที่ 2/2569\r\n2. แจ้งการเตรียมความพร้อมในการบริการจัดการเวลาเรียนและติดตามภาระงานที่ได้รับมอบหมายของอาจารย์ผู้สอนแต่ท่าน เนื่องจากนักศึกษาได้รับมอบหมายให้เป็นตัวแทนในการแข่งขันทักษะวิชาชีพ ของแผนกวิชาการจัดการ', 'ไม่พบปัญกา เนื่องจาก นักศึกษาได้ประสานกับอาจารย์ผู้สอนเรียบร้อยแล้ว', '-', 423, '2026-10-28 13:38:19'),
(32, 2, 5, 3, '2569', '2', 'โครงการด้านบัญชี 2', 'การเดินทางยังลำบาก', 'สอบถามแก้ไขช่วงการเดินทาง', 434, '2026-10-28 13:48:18'),
(33, 2, 1, 5, '2569', '2', 'การมาเรียน การลา และมาสาย ในภาคเรียนที่2`', 'ไม่พบ', '-', 409, '2026-10-28 13:50:00'),
(34, 2, 4, 2, '2569', '2', 'อบรบ', 'ไม่มี', 'ไม่มี', 447, '2026-10-28 13:57:39'),
(35, 2, 2, 4, '2569', '2', 'เกี่ยวกับการมาเรียนให้ตรงเวลา การแต่งกายให้ถูกต้องตามระเบียบของวิทยาลัย การเตรียมความพร้อมก่อนเข้าเรียน และการส่งงานตามกำหนดเวลา พร้อมทั้งเน้นย้ำให้นักเรียนมีความรับผิดชอบต่อตนเองและหน้าที่ของนักเรียน หากพบปัญหาด้านการเรียนหรือปัญหาส่วนตัว สามารถปรึกษาครูที่ปรึกษาได้ เพื่อร่วมกันหาแนวทางแก้ไขอย่างเหมาะสม', NULL, NULL, 432, '2026-10-28 14:42:10'),
(36, 2, 3, 5, '2569', '2', 'การลงทะเบียนเรียน ของนักเรียน นักศึกษา', '-', '-', 428, '2026-10-28 14:44:57'),
(37, 2, 2, 5, '2569', '2', 'อบรมเรื่องความสามัครคี การอยู่ร่วมกันต้องช่วยเหลือกัน,การเข้สร่วมกิจกรรมหน้าเสาธง', '-', 'ว่ากล่าวตักเตือน', 431, '2026-10-28 15:20:29'),
(38, 2, 3, 4, '2569', '2', 'การลงทะเบียน', 'เรื่องการลงทะเบียน', 'ขยายเวลาการลงทะเบียน', 412, '2026-10-28 20:29:41'),
(39, 2, 1, 1, '2569', '2', 'การเข้าเรียน ตารางเรียน ห้องเรียนของแต่ละวิชาของผู้เรียน กิจกรรมในวิทยาลัยในภาคเรียนนี้', 'ผู้เรียนบางคนยังเดินทางมาเรียนลำบาก เนื่องจากน้ำยังท่วมขัง', NULL, 424, '2026-10-29 07:51:12'),
(40, 2, 1, 4, '2569', '2', 'เรื่องแจ้งให้ทราบ การลงทะเบียนเรียน  ภาคเรียนที่ 2 ปีกาศึกษา 2569', 'น้ำท่วมบ้าน ของนักเรียน ระดับชั้น ปวช.1  ', 'ให้การช่วยเหลือเบื้องต้น แจกถุงยังชีพ ', 429, '2026-10-29 08:49:57'),
(41, 1, 4, 1, '2569', '2', 'การเฝ้าระวังสัตว์มีพิษหลังเกิดอุทกภัย', '-', '-', 413, '2026-10-29 13:59:49'),
(42, 2, 4, 1, '2569', '2', 'การเข้ากิจกรรมเข้าแถว และกิจกรรมชมรมวิชาชีพ', 'ให้แก้กิจกรรมให้ครบก่อนออกฝึกงาน', '-', 413, '2026-10-29 14:03:36'),
(43, 2, 2, 2, '2569', '2', '1. แจ้งนักเรียนเรื่องการลงทะเบียนเรียน ประจำภาคเรียนที่ 2/2569\r\n2. แจ้งเรื่องวิธีการเช็คชื่อกิจกรรมหน้าเสาธงตอนเช้า\r\n3. อบรมคุณธรรม จริยธรรมให้แก่นักเรียน', '-', '-', 410, '2026-11-04 11:50:25'),
(44, 2, 5, 1, '2569', '2', 'การเตรียมตัวทำโครงงานจบ', 'เรื่องทุนทรัพย์', 'ปรับแก้ปัญหาโดยด่วน', 421, '2026-11-04 12:09:18'),
(45, 3, 3, 2, '2569', '2', 'อบรมการลงทะเบียนเรียน', NULL, NULL, 430, '2026-11-04 13:10:15'),
(46, 3, 4, 4, '2569', '2', 'เรื่องการมาเรียน การทำกิจกรรมหน้าเสาธง', '-', '-', 416, '2026-11-04 13:15:58'),
(47, 3, 5, 4, '2569', '2', 'ให้คำแนะนำการสืบค้นแหล่งข้อมูลอ้างอิงงานวิจัยที่เกี่ยวข้องประกอบการจัดทำโครงการ ระดับ ปวส. ', 'ไม่พบปัญหา นักศึกษาได้รับการสาธิตวิธีการสืบค้นข้อมูลฯ จากครูที่ปรึกษา จากนั้นลงมือปฏิบัติด้วยตนเอง ผลลัพธ์คือได้แหล่งข้อมูลที่ต้องการสืบค้นตรงตามวัตถุประสงค์', 'ส่งข้อมูลแหล่งสืบค้นให้นักศึกษาทุกคนได้บันทึกไว้ในการสืบค้นครั้งต่อไป', 423, '2026-11-04 13:18:28'),
(48, 3, 1, 3, '2569', '2', 'การเตรียมความพร้อมในการแข่งขันทักษะวิชาชีพ ระดับสำนักงานอาชีวศึกษาจังหวัด', NULL, NULL, 415, '2026-11-04 13:27:10'),
(49, 3, 4, 5, '2569', '2', 'การเข้าซ้อมในการแข่งขันทักษะวิชาชีพและทักษะพื้นฐานในวันที่ 5-6 พฤศจิกายน 2569 ระดับจังหวัด ที่วิทยาลัยเทคนิคนครนายก', '-', '-', 411, '2026-11-04 13:37:48'),
(50, 3, 5, 3, '2569', '2', 'การแข่งขันทักษะ', '-', '-', 434, '2026-11-04 13:38:58'),
(51, 3, 4, 2, '2569', '2', 'การเดินทางมาวิทยาลัย\r\nสอบถามเรื่องน้ำท่วม\r\nการเยี่ยมบ้าน\r\n', NULL, NULL, 447, '2026-11-04 13:39:36'),
(52, 3, 4, 1, '2569', '2', 'การเข้าร่วมกิจกรรมชมรมวิชาชีพ และกิจกรรมหน้าเสาธง', 'การไม่มาเข้าแถวอาจจะทำให้ตกกิจกรรม', 'ไม่ให้ผู้ที่มีผลกิจกรรมไม่ผ่าน ออกฝึกงาน', 413, '2026-11-04 13:41:11'),
(53, 3, 5, 1, '2569', '2', 'เรื่องทรงผม', 'ไม่มี', 'ให้เริ่มปรับเพื่อเตรียมความพร้อมสู่โลกการทำงาน', 421, '2026-11-04 13:55:13'),
(54, 3, 1, 5, '2569', '2', 'การแต่งกาย มาเรียน ', 'แต่งตัวให้ถูกต้องตามระเบียงวิทยาลัย', 'พูดคุยกับนักเรียน ให้แนวทาง', 409, '2026-11-04 14:16:01'),
(55, 3, 2, 4, '2569', '2', 'การรับผิดชอบต่อตนเองและหน้าที่” ให้คำแนะนำและปลูกฝังให้นักเรียนมีความรับผิดชอบต่อตนเองและส่วนรวม เน้นย้ำเรื่องการมาเรียนตรงเวลา การส่งงานตามกำหนด การปฏิบัติตามกฎระเบียบของสถานศึกษา และการมีน้ำใจต่อเพื่อนร่วมชั้น พร้อมทั้งเปิดโอกาสให้นักเรียนได้สะท้อนความคิดเห็นและทบทวนพฤติกรรมของตนเอง เพื่อหาแนวทางในการปรับปรุงและพัฒนาตนเองให้ดียิ่งขึ้น', NULL, NULL, 432, '2026-11-04 14:46:04'),
(56, 3, 2, 5, '2569', '2', 'แจ้งเรื่องการเข้าร่วมกิจกรรมเข้าแถวหน้าเสาธง', '-', '-', 431, '2026-11-04 15:05:41'),
(57, 3, 2, 2, '2569', '2', '1. แจ้งนักเรียนเรื่องการลงทะเบียนเรียนให้เรียบร้อย\r\n2. แจ้งให้นักเรียนเตรียมส่งเอกสารรับเงินเรียนฟรี\r\n3. อบรมคุณธรรม จริยธรรมให้กับนักเรียน', 'นักเรียนแจ้งความประสงค์อยากให้ไปเยี่ยมบ้านพัก', '-', 410, '2026-11-04 15:35:01'),
(58, 3, 2, 3, '2569', '2', 'ฝึกซ้อมนร.เเข่งทักษะ', '-', '-', 418, '2026-11-04 16:53:27'),
(59, 3, 3, 3, '2569', '2', 'ฝึกซ้อมนร.เเข่งทักษะ', '-', '-', 418, '2026-11-04 16:54:02'),
(60, 3, 5, 5, '2569', '2', 'แจ้งเรื่องการเข้าร่วมกิจกรรมแข่งขันทักษะวิชาชีพ และการแข่งขันสิ่งประดิษฐ์คนรุ่นใหม่ รวมถึงแจ้งเรื่องการลงทะเบียนเรียน', 'นักเรียนบางคนแต่งกายไม่เรียบร้อยและมาสาย', 'ได้แจ้งให้แต่งกายให้เรียบร้อยและให้มาเช้าขึ้น', 408, '2026-11-04 16:58:13'),
(61, 3, 2, 1, '2569', '2', '-เตรียมเอกสารเรียนฟรีให้รีบดำเนินการ\r\n-รีบดำเนินการชำระค่าลงทะเบียน\r\n-ดำเนินการเตรียหาที่ฝึกงาน', NULL, NULL, 426, '2026-11-05 07:41:06'),
(62, 3, 1, 1, '2569', '2', 'ย้ำเรืื่องการเข้าแถว การเข้าเรียนของนักเรียน การขับขี่รถจักรยานยนต์ในการมาวิทยาลัย', NULL, NULL, 424, '2026-11-05 07:52:24'),
