--
-- Table structure for table `sdq_assessments`
--

CREATE TABLE `sdq_assessments` (
  `id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  `rater_type` varchar(16) NOT NULL CHECK (`rater_type` in ('student','teacher','parent')),
  `academic_year` varchar(16) NOT NULL,
  `semester` varchar(4) NOT NULL CHECK (`semester` in ('1','2')),
  `rater_name` text DEFAULT NULL,
  `answers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`answers`)),
  `gate_answer` int(11) DEFAULT NULL,
  `duration` int(11) DEFAULT NULL,
  `distress` int(11) DEFAULT NULL,
  `impact_home` int(11) DEFAULT NULL,
  `impact_friends` int(11) DEFAULT NULL,
  `impact_class` int(11) DEFAULT NULL,
  `impact_leisure` int(11) DEFAULT NULL,
  `overall_disruption` int(11) DEFAULT NULL,
  `submitted_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

