--
-- Table structure for table `student_home_visit_status`
--

CREATE TABLE `student_home_visit_status` (
  `id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  `academic_year` varchar(16) NOT NULL,
  `semester` varchar(4) NOT NULL CHECK (`semester` in ('1','2')),
  `status` varchar(32) NOT NULL CHECK (`status` in ('dropped_out','unreachable','long_absence')),
  `note` text DEFAULT NULL,
  `set_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

