(113, 408, 2, '2026-10-19', '21910-2017', 'การพัฒนาโปรแกรมบนอุปกรณ์พกพา', '08:00:00', '12:00:00', 'ปวช.3 ทธ.', 0, NULL, 'การแนะนำรายวิชา จุดประสงค์รายวิชา สมรรถนะรายวิชา คำอธิบายรายวิชา และแนวทางการจัดการเรียนรู้', 'ครูผู้สอนชี้แจงรายละเอียดเกี่ยวกับรายวิชา จุดประสงค์การเรียนรู้ สมรรถนะรายวิชา คำอธิบายรายวิชา เกณฑ์การวัดและประเมินผล รวมถึงข้อตกลงในการจัดการเรียนการสอน พร้อมอธิบายความสำคัญของการพัฒนาโปรแกรมบนอุปกรณ์พกพา และเปิดโอกาสให้นักเรียนแสดงความคิดเห็นและซักถาม', 'นักเรียนมีความรู้ความเข้าใจเกี่ยวกับรายละเอียดและขอบเขตของรายวิชา ทราบแนวทางการจัดการเรียนรู้ เกณฑ์การประเมินผล และเห็นความสำคัญของการพัฒนาโปรแกรมบนอุปกรณ์พกพา', 'นักเรียนบางส่วนยังขาดความรู้พื้นฐานเกี่ยวกับการพัฒนาแอปพลิเคชันบนอุปกรณ์พกพา', 'ครูผู้สอนทบทวนความรู้พื้นฐานเกี่ยวกับการเขียนโปรแกรมและการทำงานของแอปพลิเคชัน พร้อมยกตัวอย่างประกอบเพื่อเตรียมความพร้อมก่อนเข้าสู่บทเรียน', 5, 1, 4, '2026-10-25 21:33:12', '2026-11-02 10:27:08', NULL, '2569', '2'),
(169, 408, 2, '2026-11-02', '21910-2017', 'การพัฒนาโปรแกรมบนอุปกรณ์พกพา', '08:00:00', '12:00:00', 'ปวช.3 ทธ.', 0, NULL, 'การเตรียมเครื่องมือและสภาพแวดล้อมสำหรับการพัฒนาโปรแกรมบนอุปกรณ์พกพา การติดตั้งโปรแกรมพัฒนาบูรณาการ (IDE) และการกำหนดค่าตัวแปรสภาพแวดล้อม (Environment Variables)', 'ครูอธิบายความสำคัญและองค์ประกอบของเครื่องมือที่ใช้ในการพัฒนาโปรแกรมบนอุปกรณ์พกพา แนะนำขั้นตอนการติดตั้งโปรแกรมพัฒนาบูรณาการ (IDE) และชุดเครื่องมือที่เกี่ยวข้อง พร้อมสาธิตการตรวจสอบและกำหนดค่าตัวแปรสภาพแวดล้อม (Environment Variables) ให้นักเรียนศึกษาและฝึกปฏิบัติตามขั้นตอน', 'นักเรียนมีความรู้ความเข้าใจเกี่ยวกับเครื่องมือและสภาพแวดล้อมในการพัฒนาโปรแกรม สามารถอธิบายขั้นตอนการติดตั้ง IDE และการกำหนดค่าตัวแปรสภาพแวดล้อมเบื้องต้นได้', 'นักเรียนบางส่วนประสบปัญหาในการติดตั้งโปรแกรม เนื่องจากข้อจำกัดด้านประสิทธิภาพของเครื่องคอมพิวเตอร์และความแตกต่างของระบบปฏิบัติการ รวมถึงยังไม่เข้าใจการกำหนดค่าตัวแปรสภาพแวดล้อม', 'ครูสาธิตขั้นตอนการติดตั้งอย่างเป็นลำดับ จัดทำแนวทางปฏิบัติให้นักเรียนศึกษาเพิ่มเติม และให้คำแนะนำเป็นรายบุคคล พร้อมตรวจสอบความถูกต้องของการติดตั้งและการกำหนดค่าระบบ', 5, 3, 2, '2026-10-25 22:19:30', '2026-11-02 10:30:34', NULL, '2569', '2'),
