(249, 411, 4, '2026-10-27', '20001-1005', 'การใช้เทคโนโลยีดิจิทัลเพื่ออาชีพ', '08:00:00', '12:00:00', 'ปวช.1ทธ./4', 0, NULL, 'หน่วยที่ 1 การใช้งานอุปกรณ์คอมพิวเตอร์', '-ครูแสดงวิธีการใช้งานอุปกรณ์เคลื่อนที่\n-ครูแสดงวิธีการใช้งานอุปกรณ์ต่อพ่วง\n-ครูอธิบายหลักการทำงานของคอมพิวเตอร์\n-ครูแสดงวิธีการใช้และการบำรุงรักษาคอมพิวเตอร์\n-ครูอธิบายการใช้เทคโนโลยีสารสนเทศ\n-ครูแสดงวิธีการใช้ระบบสารสนเทศเพื่องานอาชีพ', '-นักเรียนรู้วิธีการใช้งานอุปกรณ์เคลื่อนที่\n-นักเรียนรู้วิธีการใช้งานอุปกรณ์ต่อพ่วง\n-นักเรียนบอกหลักการทำงานของคอมพิวเตอร์\n-นักเรียนรู้วิธีการใช้และการบำรุงรักษาคอมพิวเตอร์\n-นักเรียนสามารถใช้เทคโนโลยีสารสนเทศได้\n-นักเรียนรู้วิธีการใช้ระบบสารสนเทศเพื่องานอาชีพ', '-', '-', 6, 4, 2, '2026-10-27 08:42:12', '2026-11-01 22:26:35', NULL, '2569', '2'),
