(251, 411, 7, '2026-10-27', '31910-2002', 'ระบบจัดการฐานข้อมูล', '13:00:00', '17:00:00', 'ปวส.1ทธ./4', 0, NULL, 'หน่วยที่ 1 หลักการพื้นฐานของระบบฐานข้อมูล', 'ครูอธิบายและแสดงวิธีการออกแบบการจัดเก็บข้อมูลในแฟ้มข้อมูล\nให้ทำแบบฝึกหัดบทที่1 หลักการพื้นฐานของระบบฐานข้อมูล', 'นักศึกษาสามารถออกแบบการจัดเก็บข้อมูลในแฟ้มข้อมูลได้\nทำแบบฝึกหัดบทที่1 หลักการพื้นฐานของระบบฐานข้อมูล', '-', '-', 7, 7, 0, '2026-10-27 08:42:12', '2026-11-01 22:26:35', NULL, '2569', '2'),
(252, 411, 8, '2026-10-27', '31910-2002', 'ระบบจัดการฐานข้อมูล', '17:00:00', '21:00:00', 'ปวส.1ทธ.สมทบ/4', 0, NULL, 'หน่วยที่ 1 หลักการพื้นฐานของระบบฐานข้อมูล', 'ครูอธิบายและแสดงวิธีการออกแบบการจัดเก็บข้อมูลในแฟ้มข้อมูล ให้ทำแบบฝึกหัดบทที่1 หลักการพื้นฐานของระบบฐานข้อมูล', 'นักศึกษาสามารถออกแบบการจัดเก็บข้อมูลในแฟ้มข้อมูลได้\nทำแบบฝึกหัดบทที่1 หลักการพื้นฐานของระบบฐานข้อมูล', '-', '-', 13, 12, 1, '2026-10-27 08:42:12', '2026-11-01 22:26:35', NULL, '2569', '2'),
(253, 411, 9, '2026-10-28', '21910-2012', 'โปรแกรมฐานข้อมูล', '08:00:00', '12:00:00', 'ปวช.2ทธ./4', 0, NULL, 'หน่วยที่ 1 หลักการของระบบฐานข้อมูล', 'ครูอธิบายความรู้พื้นฐานเกี่ยวกับหน่วยของข้อมูลในระบบฐานข้อมูล ครูนำเข้าสู่โปรแกรม Access ฐานข้อมูล และให้สร้างฐานข้อมูล', 'นักเรียนเข้าใจในความรู้พื้นฐานเกี่ยวกับหน่วยของข้อมูลในระบบฐานข้อมูล นักเรียนสามารถเข้าสู่โปรแกรม Access ฐานข้อมูล และสร้างฐานข้อมูลได้', 'เครื่องคอมพิวเตอร์บางเครื่องไม่มีโปรแกรม Access', 'ลงโปรแกรมในเครื่องคอมพิวเตอร์ใหม่', 11, 9, 2, '2026-10-27 08:42:12', '2026-11-01 22:26:35', NULL, '2569', '2'),
(254, 411, 10, '2026-10-29', '21910-2013', 'ระบบเครือข่ายคอมพิวเตอร์', '08:00:00', '12:00:00', 'ปวช.2ทธ./4', 0, NULL, 'ติดตั้งระบบเครือข่ายคอมพิวเตอร์แบบใช้สายตามแบบ', 'ครูอธิบายสถาปัตยกรรมและผังการเชื่อมต่อระบบเครือข่าย\nครูอธิบายวิธีการเลือกใช้วัสดุและอุปกรณ์ระบบเครือข่ายสายสัญญาณ\nครูอธิบายวิธีการประยุกต์ใช้งานติดตั้งสายสัญญาณและเต้ารับเครือข่าย\nครูแสดงตัวอย่างการติดตั้งสายสัญญาณและเต้ารับเครือข่ายคอมพิวเตอร์พร้อมเข้าหัวต่อตามมาตรฐานสากลตามขั้นตอน', 'นักเรียนเข้าใจสถาปัตยกรรมและผังการเชื่อมต่อระบบเครือข่ายได้\nนักเรียนเข้าใจวิธีการเลือกใช้วัสดุและอุปกรณ์ระบบเครือข่ายสายสัญญาณได้\nนักเรียนเข้าใจวิธีการนำมาประยุกต์ใช้งานติดตั้งสายสัญญาณและเต้ารับเครือข่ายได้\nนักเรียนสามารถติดตั้งสายสัญญาณและเต้ารับเครือข่ายคอมพิวเตอร์พร้อมเข้าหัวต่อตามมาตรฐานสากลตามขั้นตอนได้ถูกต้อง', 'นักเรียนบางคนเข้าเรียนช้า', 'ครูสอบถามถึงปัญหาและหาวิธีแก้ไขเป็นรายบุคคล', 11, 11, 0, '2026-10-27 08:42:12', '2026-11-01 22:26:35', NULL, '2569', '2'),
(255, 411, 11, '2026-10-29', '31910-2023', 'การบำรุงรักษาคอมพิวเตอร์และอุปกรณ์พกพา', '13:00:00', '17:00:00', 'ปวส.2สทธ.มทธ./4', 0, NULL, 'หน่วยที่ 1 หลักการทำงานของคอมพิวเตอร์', '-ครูอธิบายหลักการทำงานของคอมพิวเตอร์ \n-ครูอธิบายองค์ประกอบของคอมพิวเตอร์', '-นักศึกษาทราบถึงหลักการทำงานของคอมพิวเตอร์ \n-นักศึกษาทราบถึงองค์ประกอบของคอมพิวเตอร์', '-', '-', 7, 7, 0, '2026-10-27 08:42:12', '2026-11-01 22:26:35', NULL, '2569', '2'),
(256, 411, 12, '2026-10-30', '21910-2018', 'คอมพิวเตอร์และการบำรุงรักษา', '08:00:00', '12:00:00', 'ปวช.1กจ./4', 0, NULL, 'หน่วยที่ 1 ความรู้พื้นฐานเกี่ยวกับคอมพิวเตอร์', '-การนำเข้าสู่บทเรียน \n-ครูอธิบายลักษณะรายวิชา\n-ครูอธิบายความหมายและคุณลักษณะที่สำคัญของคอมพิวเตอร์\n-ครูอธิบายยุคของคอมพิวเตอร์\n-ครูอธิบายประเภทของคอมพิวเตอร์\n-ครูอธิบายองค์ประกอบของคอมพิวเตอร์\n-ครูบอกวิธีการใช้คอมพิวเตอร์ในงานด้านต่างๆ', '-นักเรียนรู้ลักษณะรายวิชา\n-นักเรียนรู้ความหมายและคุณลักษณะที่สำคัญของคอมพิวเตอร์\n-นักเรียนทราบยุคของคอมพิวเตอร์\n-นักเรียนทราบประเภทของคอมพิวเตอร์\n-นักเรียนเข้าใจองค์ประกอบของคอมพิวเตอร์\n-นักเรียนทราบวิธีการใช้คอมพิวเตอร์ในงานด้านต่างๆ', 'นักเรียนบางคนยังไม่เข้ามาเรียน อาจเกิดจากภัยน้ำท่วม', 'ให้ตามงานที่เพื่อนทำไปแล้ว', 10, 5, 5, '2026-10-27 08:42:12', '2026-11-01 22:26:35', NULL, '2569', '2'),
(257, 411, 13, '2026-10-31', '31910-2007', 'เครือข่ายคอมพิวเตอร์และความปลอดภัย', '08:00:00', '12:00:00', 'ปวส.1ทธ.สมทบ/4', 0, NULL, 'หน่วยที่ 1 หลักการเครือข่ายคอมพิวเตอร์', '-ครูแจ้งประเภทของเครือข่ายคอมพิวเตอร์ -ประเภทของเซิร์ฟเวอร์ที่ให้บริการแบบต่างๆ', '-นักศึกษาอธิบายและบอกประเภทของเครือข่ายคอมพิวเตอร์ -นักศึกษาอธิบายประเภทของเซิร์ฟเวอร์ที่ให้บริการแบบต่างๆ', '-', '-', 13, 13, 0, '2026-10-27 08:42:12', '2026-11-01 22:26:35', NULL, '2569', '2'),
(258, 411, 14, '2026-10-31', '31910-2023', 'การบำรุงรักษาคอมพิวเตอร์และอุปกรณ์พกพา', '13:00:00', '17:00:00', 'ปวส.2สทธ.มทธ.สมทบ/4', 0, NULL, 'หน่วยที่ 1 หลักการทำงานของคอมพิวเตอร์', '-ครูอธิบายหลักการทำงานของคอมพิวเตอร์ \n-ครูอธิบายองค์ประกอบของคอมพิวเตอร์', '-นักศึกษาทราบถึงหลักการทำงานของคอมพิวเตอร์ \n-นักศึกษาทราบถึงองค์ประกอบของคอมพิวเตอร์', '-', '-', 11, 11, 0, '2026-10-27 08:42:12', '2026-11-01 22:26:35', NULL, '2569', '2'),
(259, 411, 4, '2026-10-20', '20001-1005', 'การใช้เทคโนโลยีดิจิทัลเพื่ออาชีพ', '08:00:00', '12:00:00', 'ปวช.1ทธ./4', 0, NULL, 'หน่วยที่ 1 การใช้อุปกรณ์คอมพิวเตอร์', '-การนำเข้าสู่บทเรียน\n-ครูอธิบายลักษณะรายวิชา\n-ความหมายของคอมพิวเตอร์\n-ประเภทของคอมพิวเตอร์\n-ประโยชน์ของคอมพิวเตอร์\n-องค์ประกอบของคอมพิวเตอร์\n-การใช้งานอุปกรณ์คอมพิวเตอร์\n-การใช้งานอุปกรณ์เคลื่อนที่', '-นักเรียนรู้ความหมายของคอมพิวเตอร์\n-นักเรียนรู้ประเภทของคอมพิวเตอร์\n-นักเรียนรู้ประโยชน์ของคอมพิวเตอร์\n-นักเรียนรู้องค์ประกอบของคอมพิวเตอร์\n-นักเรียนรู้การใช้งานอุปกรณ์คอมพิวเตอร์\n-นักเรียนรู้การใช้งานอุปกรณ์เคลื่อนที่', '-', '-', 6, 6, 0, '2026-10-27 08:42:13', '2026-11-01 22:26:35', NULL, '2569', '2'),
(260, 411, 6, '2026-10-19', '31910-2007', 'เครือข่ายคอมพิวเตอร์และความปลอดภัย', '08:00:00', '12:00:00', 'ปวส.1ทธ./4', 0, NULL, 'หน่วยที่ 1 หลักการเครือข่ายคอมพิวเตอร์', '-การนำเข้าสู่บทเรียน\n-ครูอธิบายลักษณะรายวิชา\n-ความหมายของระบบเครือข่ายคอมพิวเตอร์\n-หลักการทำงานของเครือข่ายคอมพิวเตอร์\n-ความสำคัญของเครือข่ายคอมพิวเตอร์', '-นักศึกษาตอบสนองและกระตือรือร้นในการรับฟังเรืองของลักษณะรายวิชา\n-นักศึกษารู้ความหมายของระบบเครือข่ายคอมพิวเตอร์\n-นักศึกษารู้หลักการทำงานของเครือข่ายคอมพิวเตอร์\n-นักศึกษารู้ความสำคัญของเครือข่ายคอมพิวเตอร์', 'นักศึกษาบางคนยังไม่สามารถมาเรียนได้เนื่องจากเกิดปัญหาด้านอุทกภัยในพื้นที่', 'ให้นักศึกษาที่มาเรียนไม่ได้ให้ตามงานและสอบถามเรื่องความเป็นอยู่', 7, 4, 3, '2026-10-27 08:42:13', '2026-11-01 22:26:35', NULL, '2569', '2'),
(261, 411, 7, '2026-10-20', '31910-2002', 'ระบบจัดการฐานข้อมูล', '13:00:00', '17:00:00', 'ปวส.1ทธ./4', 0, NULL, 'หน่วยที่ 1 หลักการพื้นฐานของระบบฐานข้อมูล', '-การนำเข้าสู่บทเรียน \n-ครูอธิบายลักษณะรายวิชา\n-บอกความหมายของข้อมูล ฐานข้อมูล และการจัดการฐานข้อมูลได้\n-บอกความเป็นมาของฐานข้อมูลได้\n-บอกองค์ประกอบและหน้าที่ของฐานข้อมูลได้\n-จำแนกข้อมูลตามโครงสร้างของข้อมูลได้', '-นักศึกษาสามารถบอกความเป็นมาของฐานข้อมูลได้\n-นักศึกษาสามารถบอกองค์ประกอบและหน้าที่ของฐานข้อมูลได้\n-นักศึกษาสามารถจำแนกข้อมูลตามโครงสร้างของข้อมูลได้', 'นักศึกษาบางคนยังไม่สามารถมาเรียนได้เนื่องจากเกิดปัญหาด้านอุทกภัยในพื้นที่', 'ให้นักศึกษาที่มาเรียนไม่ได้ให้ตามงานและสอบถามเรื่องความเป็นอยู่', 7, 3, 4, '2026-10-27 08:42:13', '2026-11-01 22:26:35', NULL, '2569', '2'),
(262, 411, 8, '2026-10-20', '31910-2002', 'ระบบจัดการฐานข้อมูล', '17:00:00', '21:00:00', 'ปวส.1ทธ.สมทบ/4', 0, NULL, 'หน่วยที่ 1 หลักการพื้นฐานของระบบฐานข้อมูล', '-การนำเข้าสู่บทเรียน \n-ครูอธิบายลักษณะรายวิชา\n-บอกความหมายของข้อมูล ฐานข้อมูล และการจัดการฐานข้อมูลได้\n-บอกความเป็นมาของฐานข้อมูลได้\n-บอกองค์ประกอบและหน้าที่ของฐานข้อมูลได้\n-จำแนกข้อมูลตามโครงสร้างของข้อมูลได้', '-นักศึกษาสามารถบอกความเป็นมาของฐานข้อมูลได้\n-นักศึกษาสามารถบอกองค์ประกอบและหน้าที่ของฐานข้อมูลได้\n-นักศึกษาสามารถจำแนกข้อมูลตามโครงสร้างของข้อมูลได้', '-', '-', 13, 13, 0, '2026-10-27 08:42:13', '2026-11-01 22:26:35', NULL, '2569', '2'),
(263, 411, 9, '2026-10-21', '21910-2012', 'โปรแกรมฐานข้อมูล', '08:00:00', '12:00:00', 'ปวช.2ทธ./4', 0, NULL, 'หน่วยที่ 1 หลักการของระบบฐานข้อมูล', '-การนำเข้าสู่บทเรียน \n-ครูอธิบายลักษณะรายวิชา\n-ความหมายของระบบฐานข้อมูล\n-คําศัพท์ที่เกี่ยวข้องกับระบบฐานข้อมูล\n-ประโยชน์ของการใช้งานโปรแกรมจัดการฐานข้อมูล', '-นักเรียนอธิบายความหมายของระบบฐานข้อมูล\n-นักเรียนอธิบายคําศัพท์ที่เกี่ยวข้องกับระบบฐานข้อมูล\n-นักเรียนบอกประโยชน์ของการใช้งานโปรแกรมจัดการฐานข้อมูล', 'นักเรียนบางคนยังไม่สามารถมาเรียนได้เนื่องจากเกิดปัญหาด้านอุทกภัยในพื้นที่', 'ให้นักเรียนที่มาเรียนไม่ได้ให้ตามงานและสอบถามเรื่องความเป็นอยู่', 11, 5, 6, '2026-10-27 08:42:13', '2026-11-01 22:26:35', NULL, '2569', '2'),
(264, 411, 10, '2026-10-22', '21910-2013', 'ระบบเครือข่ายคอมพิวเตอร์', '08:00:00', '12:00:00', 'ปวช.2ทธ./4', 0, NULL, 'หน่วยที่ 1 พื้นฐานระบบเครือข่ายคอมพิวเตอร์', '-การนำเข้าสู่บทเรียน \n-ครูอธิบายลักษณะรายวิชา\n-ความหมายของระบบเครือข่าย\n-ประโยชน์ของเครือข่ายคอมพิวเตอร์\n-หลักการทำงานของระบบเครือข่าย', '-นักเรียนอธิบายความหมายของระบบเครือข่าย\n-นักเรียนบอกประโยชน์ของเครือข่ายคอมพิวเตอร์\n-นักเรียนอธิบายหลักการทำงานของระบบเครือข่าย', 'นักเรียนบางคนยังไม่สามารถมาเรียนได้เนื่องจากเกิดปัญหาด้านอุทกภัยในพื้นที่', 'ให้นักเรียนที่มาเรียนไม่ได้ให้ตามงานและสอบถามเรื่องความเป็นอยู่', 11, 5, 6, '2026-10-27 08:42:13', '2026-11-01 22:26:35', NULL, '2569', '2'),
(265, 411, 11, '2026-10-22', '31910-2023', 'การบำรุงรักษาคอมพิวเตอร์และอุปกรณ์พกพา', '13:00:00', '17:00:00', 'ปวส.2สทธ.มทธ./4', 0, NULL, 'หน่วยที่ 1 หลักการทำงานของคอมพิวเตอร์', '-การนำเข้าสู่บทเรียน \n-ครูอธิบายลักษณะรายวิชา \n-ความหมายของคอมพิวเตอร์\n-ประเภทของคอมพิวเตอร์\n-หลักการทำงานของคอมพิวเตอร์\n-องค์ประกอบของคอมพิวเตอร์', '-นักศึกษาบอกความหมายของคอมพิวเตอร์ได้\n-นักศึกษาอธิบายประเภทของคอมพิวเตอร์ได้\n-นักศึกษาอธิบายหลักการทำงานของคอมพิวเตอร์ได้\n-นักศึกษาอธิบายองค์ประกอบของคอมพิวเตอร์ได้', '-', '-', 7, 7, 0, '2026-10-27 08:42:13', '2026-11-01 22:26:35', NULL, '2569', '2'),
(266, 411, 12, '2026-10-23', '21910-2018', 'คอมพิวเตอร์และการบำรุงรักษา', '08:00:00', '12:00:00', 'ปวช.1กจ./4', 1, 'วันหยุดราชการ', NULL, NULL, NULL, NULL, NULL, 10, NULL, NULL, '2026-10-27 08:42:13', '2026-11-01 22:26:35', 'holiday', '2569', '2'),
(267, 411, 13, '2026-10-24', '31910-2007', 'เครือข่ายคอมพิวเตอร์และความปลอดภัย', '08:00:00', '12:00:00', 'ปวส.1ทธ.สมทบ/4', 0, NULL, 'หน่วยที่ 1 หลักการเครือข่ายคอมพิวเตอร์', '-การนำเข้าสู่บทเรียน -ครูอธิบายลักษณะรายวิชา -ความหมายของระบบเครือข่ายคอมพิวเตอร์ -หลักการทำงานของเครือข่ายคอมพิวเตอร์ -ความสำคัญของเครือข่ายคอมพิวเตอร์', '-นักศึกษาตอบสนองและกระตือรือร้นในการรับฟังเรืองของลักษณะรายวิชา -นักศึกษารู้ความหมายของระบบเครือข่ายคอมพิวเตอร์ -นักศึกษารู้หลักการทำงานของเครือข่ายคอมพิวเตอร์ -นักศึกษารู้ความสำคัญของเครือข่ายคอมพิวเตอร์', '-', '-', 13, 12, 1, '2026-10-27 08:42:13', '2026-11-01 22:26:35', NULL, '2569', '2'),
(268, 411, 14, '2026-10-24', '31910-2023', 'การบำรุงรักษาคอมพิวเตอร์และอุปกรณ์พกพา', '13:00:00', '17:00:00', 'ปวส.2สทธ.มทธ.สมทบ/4', 0, NULL, 'หน่วยที่ 1 หลักการทำงานของคอมพิวเตอร์', '-การนำเข้าสู่บทเรียน -ครูอธิบายลักษณะรายวิชา -ความหมายของคอมพิวเตอร์ -ประเภทของคอมพิวเตอร์ -หลักการทำงานของคอมพิวเตอร์ -องค์ประกอบของคอมพิวเตอร์', '-นักศึกษาบอกความหมายของคอมพิวเตอร์ได้ -นักศึกษาอธิบายประเภทของคอมพิวเตอร์ได้ -นักศึกษาอธิบายหลักการทำงานของคอมพิวเตอร์ได้ -นักศึกษาอธิบายองค์ประกอบของคอมพิวเตอร์ได้', '-', '-', 11, 11, 0, '2026-10-27 08:42:13', '2026-11-01 22:26:35', NULL, '2569', '2'),
(279, 411, 4, '2026-11-03', '20001-1005', 'การใช้เทคโนโลยีดิจิทัลเพื่ออาชีพ', '08:00:00', '12:00:00', 'ปวช.1ทธ./4', 0, NULL, 'หน่วยที่ 2 การใช้งานระบบปฏิบัติการ', '1.ครูอธิบายความหมายและประเภทของระบบปฏิบัติการ\n2.ครูอธิบายส่วนประกอบของระบบปฏิบัติการ\n3.ครูแสดงวิธีการประยุกต์ใช้วินโดว์และการจัดการไฟล์\n4.ครูอธิบายวิธีการใช้เมาส์\n5.ครูอธิบายวิธีการเปิดปิดเครื่องคอมพิวเตอร์\n6.ครูอธิบายคู่มือการใช้งานระบบปฏิบัติการ windows 11', '1.นักเรียนเข้าใจและรู้ความหมายและประเภทของระบบปฏิบัติการได้\n2.นักเรียนเข้าใจส่วนประกอบของระบบปฏิบัติการได้\n3.นักเรียนสามารถแสดงวิธีการประยุกต์ใช้วินโดว์และการจัดการไฟล์ได้อย่างถูกต้อง\n4.นักเรียนเข้าใจวิธีการใช้เมาส์ได้อย่างถูกต้อง\n5.นักเรียนเข้าใจวิธีการเปิดปิดเครื่องคอมพิวเตอร์ได้อย่างถูกต้อง\n6.นักเรียนเข้าใจและทำงานอินโฟกราฟิกเรื่องคู่มือการใช้งานระบบปฏิบัติการ windows 11 ส่งในคาบเรียนได้', 'นักเรียนบางคนติดภาระกิจในการฝึกซ้อมแข่งขันทักษะ', 'ให้นนักเรียนติดตามงานแล้วทำส่งในภายหลัง', 6, 6, 0, '2026-10-27 08:43:42', '2026-11-06 06:45:00', NULL, '2569', '2'),
(280, 411, 6, '2026-11-02', '31910-2007', 'เครือข่ายคอมพิวเตอร์และความปลอดภัย', '08:00:00', '12:00:00', 'ปวส.1ทธ./4', 0, NULL, 'หน่วยที่ 2 รูปแบบของระบบเครือข่าย', '1. ครูอธิบายเครือข่ายแบบบัส (Bus Topology)  \n   2. ครูอธิบายเครือข่ายแบบสตาร์ (Star Topology) \n   3. ครูอธิบายเครือข่ายแบบริง (Ring Topology) \n   4. ครูอธิบายเครือข่ายแบบผสม (Hybrid Topology)', '1. นักศึกษาเข้าใจและสามารถบอกเครือข่ายแบบบัส (Bus Topology)  ได้ถูกต้อง\n   2. นักศึกษาเข้าใจและสามารถบอกเครือข่ายแบบสตาร์ (Star Topology)  ได้ถูกต้อง\n   3. นักศึกษาเข้าใจและสามารถบอกเครือข่ายแบบริง (Ring Topology)  ได้ถูกต้อง\n   4. นักศึกษาเข้าใจและสามารถบอกเครือข่ายแบบผสม (Hybrid Topology) ได้ถูกต้อง', 'นักศึกษาบางคนติดภาระกิจในการฝึกซ้อมแข่งขันทักษะ', 'ให้นักศึกษาติดตามงานแล้วทำส่งในภายหลัง', 7, 6, 1, '2026-10-27 08:43:42', '2026-11-02 11:29:54', NULL, '2569', '2'),
(281, 411, 7, '2026-11-03', '31910-2002', 'ระบบจัดการฐานข้อมูล', '13:00:00', '17:00:00', 'ปวส.1ทธ./4', 0, NULL, 'หน่วยที่ 2 ขั้นตอนการพัฒนาระบบฐานข้อมูล', '1. ครูอธิบายศัพท์พื้นฐานของฐานข้อมูล\n2.  ครูอธิบายความสัมพันธ์ระหว่างเอนทิตี้\n3. ครูอธิบายรูปแบบของข้อมูลแต่ละประเภท\n4. ครูอธิบายคุณลักษณะที่สำคัญของรูปแบบฐานข้อมูล', '1. นักศึกษาสามารถอธิบายศัพท์พื้นฐานของฐานข้อมูลได้\n2.  นักศึกษาสามารถบอกความสัมพันธ์ระหว่างเอนทิตีได้\n3. นักศึกษาสามารถบอกรูปแบบของข้อมูลแต่ละประเภทได้\n4. นักศึกษาสามารถบอกคุณลักษณะที่สำคัญของรูปแบบฐานข้อมูลได้', 'นักศึกษาบางคนติดภาระกิจในการฝึกซ้อมแข่งขันทักษะ', 'ให้นักศึกษาติดตามงานแล้วทำส่งในภายหลัง', 7, 7, 0, '2026-10-27 08:43:42', '2026-11-03 10:20:16', NULL, '2569', '2'),
(282, 411, 8, '2026-11-03', '31910-2002', 'ระบบจัดการฐานข้อมูล', '17:00:00', '21:00:00', 'ปวส.1ทธ.สมทบ/4', 0, NULL, 'หน่วยที่ 2 ขั้นตอนการพัฒนาระบบฐานข้อมูล', '1. ครูอธิบายศัพท์พื้นฐานของฐานข้อมูล\n2.  ครูอธิบายความสัมพันธ์ระหว่างเอนทิตี้\n3. ครูอธิบายรูปแบบของข้อมูลแต่ละประเภท\n4. ครูอธิบายคุณลักษณะที่สำคัญของรูปแบบฐานข้อมูล', '1. นักศึกษาสามารถอธิบายศัพท์พื้นฐานของฐานข้อมูลได้\n2.  นักศึกษาสามารถบอกความสัมพันธ์ระหว่างเอนทิตีได้\n3. นักศึกษาสามารถบอกรูปแบบของข้อมูลแต่ละประเภทได้\n4. นักศึกษาสามารถบอกคุณลักษณะที่สำคัญของรูปแบบฐานข้อมูลได้', '-', '-', 13, 13, 0, '2026-10-27 08:43:42', '2026-11-03 10:20:20', NULL, '2569', '2'),
(283, 411, 9, '2026-11-04', '21910-2012', 'โปรแกรมฐานข้อมูล', '08:00:00', '12:00:00', 'ปวช.2ทธ./4', 0, NULL, 'หน่วยที่ 2 ชนิดและลักษณะของฐานข้อมูล', '1.ครูอธิบายชนิดและลักษณะของฐานข้อมูล\n2.ครูอธิบายโปรแกรมจัดการฐานข้อมูล\n3.ครูอธิบายฐานข้อมูล\n4.ครูแสดงวิธีการใช้งานโปรแกรม Access', '1.นักเรียนบอกชนิดและลักษณะของฐานข้อมูลได้\n2.นักเรียนเข้าใจโปรแกรมจัดการฐานข้อมูลได้อย่างถูกต้อง\n3.นักเรียนเข้าใจฐานข้อมูลได้\n4.นักเรียนสามารถใช้งานโปรแกรม Access ได้อย่างถูกต้อง', 'นักเรียนบางคนติดภาระกิจในการฝึกซ้อมแข่งขันทักษะ', 'ให้นักเรียนติดตามงานแล้วทำส่งในภายหลัง', 11, 9, 2, '2026-10-27 08:43:42', '2026-11-06 06:44:26', NULL, '2569', '2'),
(284, 411, 10, '2026-11-05', '21910-2013', 'ระบบเครือข่ายคอมพิวเตอร์', '08:00:00', '12:00:00', 'ปวช.2ทธ./4', 0, NULL, 'หน่วยที่ 2 ติดตั้งระบบเครือข่ายคอมพิวเตอร์แบบไร้สายตามแบบ', 'ครูอธิบายการเชื่อมต่อแบบไร้สาย\nครูอธิบายอุปกรณ์การเชื่อมต่อแบบไร้สาย\nครูแสดงตัวอย่างการเชื่อมต่อแบบไร้สาย', 'นักเรียนเข้าใจการเชื่อมต่อแบบไร้สายได้อย่างถูกต้อง\nนักเรียนบอกอุปกรณ์การเชื่อมต่อแบบไร้สายได้\nนักเรียนปฏิบัติวิธีการเชื่อมต่อแบบไร้สายได้', 'นักเรียนบางคนติดภาระกิจในการแข่งขันทักษะ', 'ให้นักเรียนติดตามงานแล้วทำส่งในภายหลัง', 11, 6, 5, '2026-10-27 08:43:42', '2026-11-06 06:43:56', NULL, '2569', '2'),
(285, 411, 11, '2026-11-05', '31910-2023', 'การบำรุงรักษาคอมพิวเตอร์และอุปกรณ์พกพา', '13:00:00', '17:00:00', 'ปวส.2สทธ.มทธ./4', 0, NULL, 'หน่วยที่ 2 หลักการทำงานของระบบปฏิบัติการไมโครคอมพิวเตอร์', 'ครูอธิบายความหมายของระบบปฏิบัติการ\nครูอธิบายประเภทของระบบปฏิบัติการ\nครูอธิบายหน้าที่ของระบบปฏิบัติการ', 'นักศึกษาเข้าใจความหมายของระบบปฏิบัติการได้\nนักศึกษารู้ประเภทของระบบปฏิบัติการได้\nนักศึกษาเข้าใจหน้าที่ของระบบปฏิบัติการได้', 'นักศึกษาบางคนติดภาระกิจในการทำสิ่งประดิษฐ์', 'ให้นักศึกษาติดตามงานแล้วทำส่งในภายหลัง', 7, 4, 3, '2026-10-27 08:43:42', '2026-11-06 06:43:16', NULL, '2569', '2'),
