(1065, 408, 2, '2026-10-26', '21910-2017', 'การพัฒนาโปรแกรมบนอุปกรณ์พกพา', '08:00:00', '12:00:00', 'ปวช.3 ทธ.', 0, NULL, 'ระบบสถาปัตยกรรมและเครื่องมือพัฒนาโปรแกรมบนอุปกรณ์พกพา ความรู้พื้นฐานเกี่ยวกับระบบปฏิบัติการ และความแตกต่างระหว่าง Android และ iOS', 'ครูผู้สอนอธิบายความรู้พื้นฐานเกี่ยวกับระบบปฏิบัติการบนอุปกรณ์พกพา ศึกษาโครงสร้างและสถาปัตยกรรมของระบบ Android และ iOS เปรียบเทียบความแตกต่างของระบบปฏิบัติการ รวมถึงอธิบายข้อกำหนดขั้นต่ำด้านฮาร์ดแวร์และซอฟต์แวร์สำหรับการพัฒนาโปรแกรม พร้อมยกตัวอย่างเครื่องมือที่ใช้ในการพัฒนาแอปพลิเคชัน', 'นักเรียนมีความรู้ความเข้าใจเกี่ยวกับระบบปฏิบัติการและสถาปัตยกรรมของอุปกรณ์พกพา สามารถอธิบายความแตกต่างระหว่าง Android และ iOS รวมถึงระบุเครื่องมือและความต้องการพื้นฐานสำหรับการพัฒนาโปรแกรมบนอุปกรณ์พกพาได้', 'นักเรียนบางส่วนยังขาดความเข้าใจเกี่ยวกับโครงสร้างสถาปัตยกรรมและข้อแตกต่างของระบบปฏิบัติการบนอุปกรณ์พกพา', 'ครูผู้สอนใช้สื่อประกอบการสอนและยกตัวอย่างการใช้งานจริง เปรียบเทียบระบบปฏิบัติการ Android และ iOS เพื่อให้นักเรียนเข้าใจได้ง่ายขึ้น พร้อมเปิดโอกาสให้ซักถามและทบทวนความรู้', 5, 4, 1, '2026-11-02 10:27:10', '2026-11-02 10:29:38', NULL, '2569', '2'),
